28	using ::sg::fused::gfx942::PersistentContext;
29	using ::sg::fused::gfx942::TaskQueue;
30	using ::sg::fused::gfx942::GridBarrier;
31	
32	enum class FuseTier : int { L1 = 1, L3 = 3 };
33	
34	// Optimizer stage — the fused tail. Pulls tensors from the queue and applies the
35	// REAL apply_optimizer<Opt> elementwise over this CU's resident state slice.
36	// #6 — per-Opt pointer rebase via `if constexpr` (AMD twin of the sm_90 form):
37	// only the pointers the chosen optimizer dereferences are rebased to the tensor
38	// slice; the dead rebases are compiled out, lowering the tail's VGPR/local
39	// footprint. `ts` copies the const& `st` (scalar hyperparams must be present).
40	template <OptId Opt>
41	__device__ __forceinline__ FusedOptState rebase_state(const FusedOptState& st,
42	                                                       long long off) {
43	    FusedOptState ts = st;
44	    if constexpr (Opt == OptId::AdamW || Opt == OptId::Lion ||
45	                  Opt == OptId::Grokfast || Opt == OptId::GrokAdamW ||
46	                  Opt == OptId::LookSAM || Opt == OptId::Prodigy ||
47	                  Opt == OptId::NeuralGrok || Opt == OptId::SuperGrok11 ||
48	                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2) {
49	        if (ts.exp_avg)    ts.exp_avg    += off;
50	    }
51	    if constexpr (Opt != OptId::Lion && Opt != OptId::Muon) {
52	        if (ts.exp_avg_sq) ts.exp_avg_sq += off;
53	    }
54	    if constexpr (Opt == OptId::Grokfast || Opt == OptId::GrokAdamW) {
55	        if (ts.ema)        ts.ema        += off;
56	    }
57	    if constexpr (Opt == OptId::Prodigy) {
58	        if (ts.s_track)    ts.s_track    += off;
59	    }
60	    if constexpr (Opt == OptId::SuperGrok11 || Opt == OptId::SuperGrok15) {
61	        if (ts.mu)         ts.mu         += off;
62	    }
63	    if constexpr (Opt == OptId::LookSAM) {
64	        if (ts.sam_dir)    ts.sam_dir    += off;
65	    }
66	    if constexpr (Opt == OptId::Muon) {
67	        if (ts.orth)       ts.orth       += off;
68	    }
69	    if constexpr (Opt == OptId::SuperGrok2) {
70	        if (ts.smart_grad) ts.smart_grad += off;
71	    }
72	    return ts;
73	}
74	
75	template <OptId Opt>
76	__device__ void fused_optimizer_stage(const PersistentContext& ctx,
77	                                       float* __restrict__ params,
78	                                       const float* __restrict__ grad,
79	                                       const int* sizes, const int* offsets,
80	                                       int step, const FusedOptState& st) {
81	    __shared__ int task_slot;
82	    TaskQueue q = ctx.queue();
83	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
84	         t = q.next_block(&task_slot)) {
85	        const int n = sizes[t];
86	        // #2 int64: off (tensor element offset into the global blob) can exceed
87	        // 2^31; rebase the slice pointers in 64-bit. Behavior-preserving.
88	        const long long off = (long long)offsets[t];
89	        const FusedOptState ts = rebase_state<Opt>(st, off);
90	        float* __restrict__ p = params + off;
91	        const float* __restrict__ g = grad + off;
92	        // #1 — float4 vectorization: each thread strides over groups of 4
93	        // CONSECUTIVE indices and calls the (transcribed canonical) per-element
94	        // apply 4× on [4j..4j+3]; the contiguous __restrict__ accesses coalesce
95	        // into 128-bit (dwordx4) global transactions. Math is CALLED, never
96	        // re-inlined; only the access pattern changes. Scalar remainder tail.
97	        const int n4 = n >> 2;
98	        for (int j = threadIdx.x; j < n4; j += blockDim.x) {
99	            const long long base = (long long)j << 2;   // #2 int64 within-tensor
100	            apply_optimizer<Opt>(p, g, base + 0, step, ts);
101	            apply_optimizer<Opt>(p, g, base + 1, step, ts);
102	            apply_optimizer<Opt>(p, g, base + 2, step, ts);
103	            apply_optimizer<Opt>(p, g, base + 3, step, ts);
104	        }
105	        for (int i = (n4 << 2) + (int)threadIdx.x; i < n; i += blockDim.x) {
106	            apply_optimizer<Opt>(p, g, (long long)i, step, ts);
107	        }
108	    }
109	}
110	
111	// Stage 5 — TRUE cross-phase fusion (bwd→opt), LDS-resident grad tile (AMD twin
112	// of the sm_90 fused_backward_optimizer_stage; see that header for the full
113	// honest-scope note). REALIZED: the backward grad and the optimizer update of
114	// the SAME tensor are fused into one queue-pulled body; grad is computed into a
115	// per-workgroup __shared__ (LDS) tile and the optimizer reads it from LDS — no
116	// global grad round-trip, and the bwd→opt grid barrier is eliminated (2 barriers
117	// → 1 per L3 step). Correct because bwd (grad = acts*act'(param)) and every
118	// apply_optimizer<Opt> are strictly element-local for a tensor, and the same
119	// workgroup owns the tensor end-to-end in one queue pull (no work-steal split).
120	// DEFERRED (documented): `acts` stays global — fwd→bwd is separated by a grid
121	// barrier + a queue reset, so under work-stealing a different workgroup may own
122	// the tensor in bwd; a workgroup-local LDS acts tile cannot cross that barrier
123	// safely. Math is still CALLED via apply_optimizer (drift-guard safe); only the
124	// grad source pointer changes to LDS. Grad value is bit-identical. 🟡 perf.
125	// SG_TUNED_GRAD_TILE — floats per LDS grad tile (AMD twin; sizes __shared__
126	// smem_grad[]). Default 1024 → byte-identical untuned build. NEEDS-PARITY for a
127	// non-default winner (LDS footprint + chunk bounds). Not registered on gfx942.
128	#ifndef SG_TUNED_GRAD_TILE
129	#define SG_TUNED_GRAD_TILE 1024
130	#endif
131	static constexpr int kGradTile = SG_TUNED_GRAD_TILE;   // floats / LDS grad tile
132	
133	template <ModelId M, OptId Opt>
134	__device__ void fused_backward_optimizer_stage(
135	        const PersistentContext& ctx,
136	        float* __restrict__ params,
137	        const float* __restrict__ acts,
138	        const int* sizes, const int* offsets,
139	        int step, const FusedOptState& st) {
140	    __shared__ int task_slot;
141	    __shared__ float smem_grad[kGradTile];
142	    TaskQueue q = ctx.queue();
143	    for (int t = q.next_block(&task_slot); t < ctx.n_tasks;
144	         t = q.next_block(&task_slot)) {
145	        const int n = sizes[t];
146	        const long long off = (long long)offsets[t];   // #2 int64 base
147	        for (int c0 = 0; c0 < n; c0 += kGradTile) {
148	            const int chunk = (n - c0 < kGradTile) ? (n - c0) : kGradTile;
149	            const long long chunk_base = off + c0;
150	            for (int i = threadIdx.x; i < chunk; i += blockDim.x) {
151	                const long long gi = chunk_base + i;
152	                smem_grad[i] = acts[gi] * model_activation_grad<M>(params[gi]);
153	            }
154	            __builtin_amdgcn_s_barrier();
155	            const FusedOptState ts = rebase_state<Opt>(st, chunk_base);
156	            float* __restrict__ p = params + chunk_base;
157	            const float* __restrict__ g = smem_grad;   // LDS-resident grad
158	            const int n4 = chunk >> 2;
159	            for (int j = threadIdx.x; j < n4; j += blockDim.x) {
160	                const long long base = (long long)j << 2;
161	                apply_optimizer<Opt>(p, g, base + 0, step, ts);
162	                apply_optimizer<Opt>(p, g, base + 1, step, ts);
163	                apply_optimizer<Opt>(p, g, base + 2, step, ts);
164	                apply_optimizer<Opt>(p, g, base + 3, step, ts);
165	            }
166	            for (int i = (n4 << 2) + (int)threadIdx.x; i < chunk;
167	                 i += blockDim.x) {
168	                apply_optimizer<Opt>(p, g, (long long)i, step, ts);
169	            }
170	            __builtin_amdgcn_s_barrier();   // tile reuse fence
171	        }
172	    }
173	}
