175	// The L3/L1 persistent megakernel. ONE launch composes the real model stages
176	// (L3 only) and the real optimizer tail, separated by the hand-built grid
177	// barrier whose last arriver resets the task-queue counter race-free.
178	template <ModelId M, OptId Opt, FuseTier Tier>
179	__global__ void
180	SG_MK_FWGS(SG_TUNED_MEGA_BLOCK, SG_TUNED_MEGA_BLOCK)
181	fused_megakernel(PersistentContext ctx,
182	                 float* __restrict__ params,
183	                 const float* __restrict__ input,
184	                 float* __restrict__ acts,
185	                 float* __restrict__ grad,
186	                 const int* __restrict__ sizes,
187	                 const int* __restrict__ offsets,
188	                 float lr, int step, FusedOptState st) {
189	    GridBarrier bar = ctx.barrier();
190	
191	    if constexpr (Tier == FuseTier::L3) {
192	        // #4: fold the next-phase task-queue reset into the grid barrier's
193	        // last-arriver critical section (sync_reset). Stage 5: bwd+opt fused, so
194	        // the L3 step is fwd → sync_reset → (bwd+opt) = 1 grid barrier.
195	        model_forward_stage<M>(ctx, params, input, acts, sizes, offsets);
196	        bar.sync_reset(ctx.g_next_task);
197	        st.lr = lr;
198	        fused_backward_optimizer_stage<M, Opt>(ctx, params, acts, sizes,
199	                                               offsets, step, st);
200	        (void)grad;   // grad is LDS-resident on L3; no global round-trip
201	    } else {
202	        st.lr = lr;
203	        fused_optimizer_stage<Opt>(ctx, params, grad, sizes, offsets, step, st);
204	    }
205	}
