211	// =========================================================================
212	//  HOST launcher (hipcc host pass only; 🟡 MI300X — not the bare amdgcn gate).
213	//  AMD twin of the sm_90 launch_fused_megakernel hang-freedom fix (Stage 1).
214	//
215	//  Same hazard: the L3 kernel rendezvouses ALL launched workgroups at
216	//  GridBarrier::sync_reset, which spins until exactly ctx.n_groups workgroups
217	//  arrive. hipLaunchKernelGGL gives no co-residency guarantee, so if the kernel
218	//  cannot place even one workgroup per CU (VGPR/LDS pressure) the resident
219	//  workgroups spin forever. MECHANISM: hipOccupancyMaxActiveBlocksPerMultiproc
220	//  caps the grid so one workgroup per CU is guaranteed resident; if occupancy is
221	//  0 we REFUSE to launch (hipErrorOutOfMemory) rather than hang. The barrier +
222	//  task counters are device-zeroed before each launch (GridBarrier reuse assumes
223	//  a zeroed start). Cells call this instead of inlining their own launch.
224	// =========================================================================
225	#if defined(__HIPCC__) && !defined(__AMDGCN__)
226	#include <hip/hip_runtime.h>
227	#include <cassert>
228	
229	namespace sg { namespace fused { namespace gfx942_mega {
230	
231	template <ModelId M, OptId Opt, FuseTier Tier>
232	hipError_t launch_fused_megakernel(
233	        PersistentContext ctx,
234	        float* params, const float* input, float* acts, float* grad,
235	        const int* sizes, const int* offsets,
236	        float lr, int step, FusedOptState st, hipStream_t stream) {
237	    int dev = 0;
238	    hipError_t err = hipGetDevice(&dev);
239	    if (err != hipSuccess) return err;
240	    int n_cus = 0;
241	    err = hipDeviceGetAttribute(&n_cus, hipDeviceAttributeMultiprocessorCount,
242	                                dev);
243	    if (err != hipSuccess) return err;
244	
245	    // Co-residency guarantee: at least one workgroup of THIS kernel must fit on
246	    // one CU, or the grid barrier of n_groups workgroups can never complete.
247	    int occ_blocks_per_cu = 0;
248	    err = hipOccupancyMaxActiveBlocksPerMultiprocessor(
249	        &occ_blocks_per_cu,
250	        reinterpret_cast<const void*>(
251	            &fused_megakernel<M, Opt, Tier>),
252	        /*blockSize=*/SG_TUNED_MEGA_BLOCK, /*dynamicSMemBytes=*/0);
253	    if (err != hipSuccess) return err;
254	    assert(occ_blocks_per_cu >= 1 &&
255	           "fused_megakernel: 0 workgroups/CU occupancy — GridBarrier would "
256	           "hang; reduce VGPR/LDS footprint or run this cell L1.");
257	    if (occ_blocks_per_cu < 1) return hipErrorOutOfMemory;
258	
259	    // §1.3: pin exactly ONE persistent workgroup per CU; occ>=1 guarantees it is
260	    // co-resident, so all n_cus workgroups rendezvous at the barrier — no hang.
261	    const unsigned launch_groups = (unsigned)n_cus;
262	    ctx.n_groups = launch_groups;
263	
264	    if (ctx.g_arrived != nullptr) {
265	        err = hipMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream);
266	        if (err != hipSuccess) return err;
267	    }
268	    if (ctx.g_generation != nullptr) {
269	        err = hipMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream);
270	        if (err != hipSuccess) return err;
271	    }
272	    if (ctx.g_next_task != nullptr) {
273	        err = hipMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream);
274	        if (err != hipSuccess) return err;
275	    }
276	
277	    st.lr = lr;
278	    dim3 grid(launch_groups), block(SG_TUNED_MEGA_BLOCK);
279	    hipLaunchKernelGGL((fused_megakernel<M, Opt, Tier>), grid, block, 0, stream,
280	                       ctx, params, input, acts, grad, sizes, offsets,
281	                       lr, step, st);
282	    return hipGetLastError();
283	}
