32	// Defensive bias-correction denominator guard (mirrors csrc/common/utils.cuh).
33	__device__ __forceinline__ float sg_safe_bc(float bc) {
34	    float abs_bc = bc < 0.0f ? -bc : bc;
35	    return abs_bc > 1e-30f ? bc : 1e-30f;
36	}
37	
38	// Compile-time optimizer selector — one value per real optimizer (no fallback).
39	enum class OptId : int {
40	    AdamW = 0, Lion = 1, Grokfast = 2, GrokAdamW = 3, LookSAM = 4,
41	    Prodigy = 5, NeuralGrok = 6, Muon = 7, SuperGrok11 = 8,
42	    SuperGrok15 = 9, SuperGrok2 = 10
43	};
44	
45	static constexpr int kPsiHidden = 16;   // neuralgrok psi-net hidden width
46	
47	// #5 — NeuralGrok psi-net weight packing in the cell's `extra` buffer (mirror of
48	// the sm_90 layout in opt_components.cuh): W1[kPsiHidden] | b1[kPsiHidden] |
49	// W2[kPsiHidden] | b2(scalar). The cell binds st.psi_W1/b1/W2 from these
50	// offsets so the device read of the psi weights is a bound pointer, not a null
51	// deref. psi_b2 stays at its 0.0f default (device scalar; host can't deref).
52	static constexpr int kPsiW1Off = 0;
53	static constexpr int kPsiB1Off = kPsiHidden;
54	static constexpr int kPsiW2Off = 2 * kPsiHidden;
55	static constexpr int kPsiB2Off = 3 * kPsiHidden;
56	static constexpr int kPsiPackFloats = 3 * kPsiHidden + 1;
57	
58	// All optimizer state any of the 11 tails may read (mirror of the sm_90 struct).
59	// A cell zero-fills the pointers its optimizer does not use; each branch touches
60	// ONLY its own optimizer's real buffers.
61	struct FusedOptState {
62	    float* exp_avg     = nullptr;
63	    float* exp_avg_sq  = nullptr;
64	    float* ema         = nullptr;
65	    const float* sam_dir = nullptr;
66	    float* s_track     = nullptr;
67	    float  d_factor    = 1.0f;
68	    float* mu          = nullptr;
69	    float  gate        = 1.0f;
70	    const float* orth  = nullptr;
71	    float  neg_lr_scale = 0.0f;
72	    float  decay_factor = 1.0f;
73	    const float* psi_W1 = nullptr;
74	    const float* psi_b1 = nullptr;
75	    const float* psi_W2 = nullptr;
76	    float        psi_b2 = 0.0f;
77	    const float* smart_grad = nullptr;
78	    float lr = 1e-3f, beta1 = 0.9f, beta2 = 0.999f, eps = 1e-8f, wd = 0.01f;
79	    float bc1 = 1.0f, bc2 = 1.0f;
80	    float alpha = 0.98f, beta = 0.0f, lamb = 2.0f, alpha_max = 1.0f;
81	};
