83	// FusedScalars — full runtime scalar set (AMD twin of the sm_90 struct). See
84	// opt_components.cuh for the C2-gap rationale: previously each cell bound only
85	// lr, freezing bc1/bc2/gate/d_factor at 1.0; this carries the live values so
86	// apply_optimizer<> (which already reads them) is no longer inert. Defaults
87	// reproduce the old inert behavior exactly. One (bc1,bc2) pair per call is valid
88	// only when all param tensors share a step counter (true in the grokking race).
89	struct FusedScalars {
90	    float lr           = 1e-3f;
91	    float beta1        = 0.9f;
92	    float beta2        = 0.999f;
93	    float eps          = 1e-8f;
94	    float wd           = 0.01f;
95	    float bc1          = 1.0f;
96	    float bc2          = 1.0f;
97	    float alpha        = 0.98f;
98	    float beta         = 0.0f;
99	    float lamb         = 2.0f;
100	    float alpha_max    = 1.0f;
101	    float gate         = 1.0f;
102	    float d_factor     = 1.0f;
103	    float neg_lr_scale = 0.0f;
104	    float decay_factor = 1.0f;
