107	__host__ __device__ __forceinline__ void apply_scalars(FusedOptState& st,
108	                                                        const FusedScalars& s) {
109	    st.lr = s.lr; st.beta1 = s.beta1; st.beta2 = s.beta2; st.eps = s.eps;
110	    st.wd = s.wd; st.bc1 = s.bc1; st.bc2 = s.bc2; st.alpha = s.alpha;
111	    st.beta = s.beta; st.lamb = s.lamb; st.alpha_max = s.alpha_max;
112	    st.gate = s.gate; st.d_factor = s.d_factor;
113	    st.neg_lr_scale = s.neg_lr_scale; st.decay_factor = s.decay_factor;
114	}
