116	// Shared Adam tail: m,v EMAs on g_eff, bias-corrected decoupled-WD apply.
117	// (bc1/bc2 un-inverted = 1-beta^t; divide — matches the algorithm headers.)
118	__device__ __forceinline__ float sg_adam_tail(
119	        float p, float g_eff, float* m_buf, float* v_buf, long long i,
120	        float b1, float b2, float eps, float bc1, float bc2,
121	        float lr, float wd) {
122	    const float m = b1 * m_buf[i] + (1.0f - b1) * g_eff;
123	    const float v = b2 * v_buf[i] + (1.0f - b2) * g_eff * g_eff;
124	    m_buf[i] = m; v_buf[i] = v;
125	    const float update = (m / sg_safe_bc(bc1)) / (__builtin_sqrtf(v / sg_safe_bc(bc2)) + eps);
126	    return p - lr * (update + wd * p);
127	}
