129	// NeuralGrok psi-net (per-element MLP over |g|). Faithful to neuralgrok_psi_forward.
130	__device__ __forceinline__ float sg_psi_forward(
131	        float abs_grad, const float* W1, const float* b1,
132	        const float* W2, float b2) {
133	    float h_acc = 0.0f;
134	#pragma unroll
135	    for (int j = 0; j < kPsiHidden; j++) {
136	        float h = W1[j] * abs_grad + b1[j];
137	        h = (h > 0.0f) ? h : 0.0f;           // ReLU
138	        h_acc += W2[j] * h;
139	    }
140	    return h_acc + b2;
141	}
