143	// SG15 per-coordinate alpha (faithful to sg15_alpha_per_coord).
144	__device__ __forceinline__ float sg_sg15_alpha(float mu_val, float ab, float am) {
145	    const float a = ab * (1.0f + mu_val);
146	    return __builtin_fminf(__builtin_fmaxf(a, 0.0f), am);
147	}
