149	// Dispatch to the REAL per-element update for the chosen optimizer. Each branch
150	// is the genuine, distinct math from csrc/algorithms/<opt>.h — no fallback.
151	template <OptId Opt>
152	__device__ __forceinline__ void apply_optimizer(
153	        float* __restrict__ params, const float* __restrict__ grad,
154	        long long i, int step, const FusedOptState& st) {
155	    (void)step;
156	    const float g = grad[i];
157	    const float p = params[i];
158	    if constexpr (Opt == OptId::AdamW) {
159	        params[i] = sg_adam_tail(p, g, st.exp_avg, st.exp_avg_sq, i,
160	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
161	                                 st.lr, st.wd);
162	    } else if constexpr (Opt == OptId::Lion) {
163	        const float ea = st.exp_avg[i];
164	        const float interp = st.beta1 * ea + (1.0f - st.beta1) * g;
165	        const float s = (interp != 0.0f) ? __builtin_copysignf(1.0f, interp) : 0.0f;
166	        st.exp_avg[i] = st.beta2 * ea + (1.0f - st.beta2) * g;
167	        params[i] = p - st.lr * (s + st.wd * p);
168	    } else if constexpr (Opt == OptId::Grokfast) {
169	        const float e = st.alpha * st.ema[i] + (1.0f - st.alpha) * g;
170	        st.ema[i] = e;
171	        const float g_amp = g + st.lamb * e;
172	        params[i] = sg_adam_tail(p, g_amp, st.exp_avg, st.exp_avg_sq, i,
173	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
174	                                 st.lr, st.wd);
175	    } else if constexpr (Opt == OptId::GrokAdamW) {
176	        const float e = st.alpha * st.ema[i] + (1.0f - st.alpha) * g;
177	        st.ema[i] = e;
178	        const float g_amp = g + st.lamb * e;
179	        params[i] = sg_adam_tail(p, g_amp, st.exp_avg, st.exp_avg_sq, i,
180	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
181	                                 st.lr, st.wd);
182	    } else if constexpr (Opt == OptId::LookSAM) {
183	        const float g_adj = (1.0f - st.alpha) * g + st.alpha * st.sam_dir[i];
184	        params[i] = sg_adam_tail(p, g_adj, st.exp_avg, st.exp_avg_sq, i,
185	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
186	                                 st.lr, st.wd);
187	    } else if constexpr (Opt == OptId::Prodigy) {
188	        const float d = st.d_factor;
189	        const float g_scaled = d * g;
190	        const float m = st.beta1 * st.exp_avg[i] + (1.0f - st.beta1) * g_scaled;
191	        const float v = st.beta2 * st.exp_avg_sq[i]
192	                        + (1.0f - st.beta2) * g_scaled * g_scaled;
193	        st.exp_avg[i] = m; st.exp_avg_sq[i] = v;
194	        st.s_track[i] += d * g;
195	        const float update = (m / sg_safe_bc(st.bc1)) / (__builtin_sqrtf(v / sg_safe_bc(st.bc2)) + st.eps);
196	        params[i] = p - d * (update + st.wd * p);     // prodigy steps with d, not lr
197	    } else if constexpr (Opt == OptId::NeuralGrok) {
198	        // psi_b2 scalar is packed at extra[kPsiB2Off] == st.psi_W2[kPsiHidden];
199	        // read it ON-DEVICE here (host can't deref the device pointer, so the
200	        // cell leaves st.psi_b2 at 0.0f). Mirrors the sm_90 opt_components fix.
201	        const float psi_b2 = (st.psi_W2 != nullptr) ? st.psi_W2[kPsiHidden]
202	                                                     : st.psi_b2;
203	        const float psi = sg_psi_forward(__builtin_fabsf(g), st.psi_W1, st.psi_b1,
204	                                         st.psi_W2, psi_b2);
205	        const float g_amp = (psi * st.alpha + st.beta) * g;
206	        params[i] = sg_adam_tail(p, g_amp, st.exp_avg, st.exp_avg_sq, i,
207	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
208	                                 st.lr, st.wd);
209	    } else if constexpr (Opt == OptId::Muon) {
210	        params[i] = p * st.decay_factor + st.neg_lr_scale * st.orth[i];
211	    } else if constexpr (Opt == OptId::SuperGrok11) {
212	        const float smart = g + (1.0f - st.gate) * st.alpha * st.mu[i];
213	        params[i] = sg_adam_tail(p, smart, st.exp_avg, st.exp_avg_sq, i,
214	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
215	                                 st.lr, st.wd);
216	    } else if constexpr (Opt == OptId::SuperGrok15) {
217	        const float a = sg_sg15_alpha(st.mu[i], st.alpha, st.alpha_max);
218	        const float smart = g + st.gate * a * st.mu[i];
219	        params[i] = sg_adam_tail(p, smart, st.exp_avg, st.exp_avg_sq, i,
220	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
221	                                 st.lr, st.wd);
222	    } else {  // OptId::SuperGrok2 — Adam apply on the meta-net smart gradient.
223	        const float gg = (st.smart_grad != nullptr) ? st.smart_grad[i] : g;
224	        params[i] = sg_adam_tail(p, gg, st.exp_avg, st.exp_avg_sq, i,
225	                                 st.beta1, st.beta2, st.eps, st.bc1, st.bc2,
226	                                 st.lr, st.wd);
227	    }
228	}
